import { POKEMON_SPRITE_IDS as _POKEMON_SPRITE_IDS } from '../../constants/balance/dexAndCapture.ts';
import { countPokedexUniqueDiscovered } from './headerSkinUnlock.ts';
import { getSpriteIdForSpecies, isKnownSpecies } from './speciesNaturalRarity.js';
